INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('25f70531-561a-5b22-9361-006c855f1afa'::uuid, '464e66ae-df8c-5b3b-9511-639e7dde6172'::uuid, 'PHOTOTHEQUE PROJET ACERO', 'Project realized', '["https://lechantier.ma/uploads/media/bac8f04c3096.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/bac8f04c3096.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.6' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('0bff963b-7184-5570-83d8-2b9a8cd63d9e'::uuid, 'a2ef25c4-aa5a-523a-837f-ee5082814165'::uuid, 'Miroir decoratif organique - Cadre fer forge noir mat - Villa luxe', 'Miroir decoratif sur mesure, forme organique tendance 2024. Cadre en fer forge finition noir mat thermolaque haute resistance. Soudure fine et invisible, design moderne pour salon villa de luxe. Realisation artisanale dans notre atelier a Marrakech. Disponible en differentes formes et dimensions sur commande. Ideal pour villas, riads et hotels boutique', '["https://lechantier.ma/uploads/pro/cmuvfc62f00quzw2w7stppm3p/cover-1791227503532-09e98396c646.webp", "https://lechantier.ma/uploads/pro/cmuvfc62f00quzw2w7stppm3p/portfolio-1791226445082-884afb7d0081.webp", "https://lechantier.ma/uploads/pro/cmuvfc62f00quzw2w7stppm3p/portfolio-1791224706885-d312be1eecc9.webp"]'::jsonb, 'https://lechantier.ma/uploads/pro/cmuvfc62f00quzw2w7stppm3p/cover-1791227503532-09e98396c646.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.2.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('cda74f3f-fa1d-5e82-a911-33dfa687a546'::uuid, 'a2ef25c4-aa5a-523a-837f-ee5082814165'::uuid, 'Porte monumentale doree 6m - Style palais Marrakech', 'Porte monumentale sur mesure hauteur 6m, en fer forge sculpte main, finition doree haute resistance. Motif zellige geometrique arabo-andalou 100% artisanal. Realisation pour mosquee / palais a Marrakech. Structure renforcee, soudure professionnelle. Maitre ferronnier specialiste ouvrages d''exception pour villas de luxe, palais et mosquees. Devis gratuit.', '["https://lechantier.ma/uploads/pro/cmuvfc62f00quzw2w7stppm3p/logo-1791222884873-480dc8055d02.webp"]'::jsonb, 'https://lechantier.ma/uploads/pro/cmuvfc62f00quzw2w7stppm3p/logo-1791222884873-480dc8055d02.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.2.3' LIMIT 1));
