INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('171890f9-bf68-54e1-aaac-cd264fae35bc'::uuid, 'c8ad79aa-d483-5bb6-bb2b-6f0d7a688258'::uuid, 'FABRICATION DES CITERNES METALLIQUE ARME', 'Afrique Découpe Laser a été mandatée pour la conception, la fabrication et la livraison de 140 citernes métalliques destinées au stockage et au transport de liquides industriels. Le projet comprend : Étude et conception technique : réalisation des plans et optimisation des découpes via logiciels spécialisés (SolidWorks) pour assurer l''assemblage.', '["https://lechantier.ma/uploads/media/7aef7aa655f7.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/7aef7aa655f7.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('416ef71d-3796-5bf5-a5a3-48abb8173fb3'::uuid, 'df015d0d-46eb-51eb-a892-7b286e1d62cf'::uuid, 'Mezzanine', 'Réalisation d’un petit mezzanine métallique destiné à un usage de bureau, permettant d’optimiser l’espace avec une solution simple, pratique et sécurisée.', '["https://lechantier.ma/uploads/media/4d2cf0a64f5a.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/4d2cf0a64f5a.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.3.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('890e3c7a-b298-5ab3-9f8f-b90638d79578'::uuid, 'df015d0d-46eb-51eb-a892-7b286e1d62cf'::uuid, 'Auvent métallique à l’entrée des merchan', 'Réalisation d’un auvent métallique à l’entrée des marchandises, offrant protection contre les intempéries et facilitant les opérations de chargement et déchargement, avec une structure solide et un design pratique.', '["https://lechantier.ma/uploads/media/16c6f2b54b99.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/16c6f2b54b99.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.3.5' LIMIT 1));
