INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('abddbb92-998e-553f-a0cb-bf6a992f0ef3'::uuid, '32d614f3-b70d-569d-837d-1279d2f681fe'::uuid, 'صناعه الهياكل المعدنيه جميع الصناعات', 'عمر اللحام هو شخصية متميزة في مجال اللحام، حيث يمتلك خبرة واسعة تمتد ل15 عامًا، وقد عمل في مختلف المواقع والصناعات، مما جعله يجمع بين الخبرة العملية والتنوع في التعامل مع التحديات المختلفة. \*الخبرة العملية:\* - \*اللحام بالقوس الكهربائي (SMAW):\* لديه خبرة واسعة في استخدام هذه الطريقة التقليدية، حيث يمكنه التعامل مع مختلف أنواع المعا 0645187598-', '["https://lechantier.ma/uploads/media/932b07199c41.webp", "https://lechantier.ma/uploads/media/deee732d8ecb.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/932b07199c41.webp', 'Larache', (SELECT id FROM public.internal_categories WHERE code = '3.3.5' LIMIT 1));
